<?php namespace App\Http\Controllers; use App\Models\Customer; use Illuminate\Http\Request;
class CustomerController extends Controller {public function index(Request $r){$customers=Customer::when($r->q,fn($q,$v)=>$q->where('full_name','like','%'.$v.'%')->orWhere('phone','like','%'.$v.'%'))->latest()->paginate(15);return view('customers.index',compact('customers'));} public function list(){return response()->json(Customer::select('id','full_name','phone')->orderBy('full_name')->get());} public function create(){return view('customers.create');} public function store(Request $r){try{$validated=$r->validate(['full_name'=>'required','phone'=>'required|unique:customers,phone','whatsapp_number'=>'nullable','email'=>'nullable|email','address'=>'nullable']);$existingCustomer=Customer::where('full_name',$r->full_name)->where('phone',$r->phone)->first();if($existingCustomer){if($r->wantsJson()){return response()->json(['error'=>'A customer with this name and phone number already exists in the system.'],422);}return back()->with('error','A customer with this name and phone number already exists in the system.')->withInput();}$validated['business_id']=auth()->user()->business_id;$validated['customer_code']='CUS-'.now()->format('Y').'-'.str_pad((string)(Customer::max('id')+1),6,'0',STR_PAD_LEFT);$customer=Customer::create($validated);if($r->transfer_vehicle_id){$vehicle=\App\Models\Vehicle::find($r->transfer_vehicle_id);if($vehicle){$vehicle->update(['customer_id'=>$customer->id]);}}if($r->wantsJson()){return response()->json($customer);}$redirectUrl=$r->input('redirect_to')?:route('customers.show',$customer);return redirect($redirectUrl)->with('success','Customer created.');}catch(\Illuminate\Validation\ValidationException $e){if($r->wantsJson()){return response()->json(['error'=>$e->getMessage(),'errors'=>$e->errors()],422);}throw $e;}} public function show(Customer $customer){$customer->load('vehicles','jobs','invoices');return view('customers.show',compact('customer'));} public function edit(Customer $customer){return view('customers.edit',compact('customer'));} public function update(Request $r,Customer $customer){$customer->update($r->validate(['full_name'=>'required','phone'=>'required','whatsapp_number'=>'nullable','email'=>'nullable|email','address'=>'nullable']));return back()->with('success','Customer updated.');} public function destroy(Customer $customer){abort(405);}}
